S = "Hakeem Force Academy"
QS = [
(S, "In which Hijri year was the Ghazwa (Battle) of Mu'tah fought?", ["6 AH", "7 AH", "8 AH", "9 AH"], 2, "The Battle of Mu'tah was fought in 8 AH (629 AD) in Jordan against the Byzantine (Roman) forces. It was the first major clash of Muslims with a non-Arab power.", "Commanders Zaid bin Haritha, Jafar bin Abi Talib and Abdullah bin Rawaha were martyred, and Khalid bin Waleed then led the army back.", [331]),
(S, "What is the full name of the conqueror of Sindh, Muhammad bin Qasim?", ["Muhammad bin Qasim al-Thaqafi", "Muhammad bin Qasim al-Hashimi", "Muhammad bin Qasim al-Qurashi", "Muhammad bin Qasim al-Ansari"], 0, "Muhammad bin Qasim belonged to the Banu Thaqif tribe of Taif, so he is known as al-Thaqafi.", "He invaded Sindh in 711-712 AD during the Umayyad rule under governor Hajjaj bin Yusuf.", [265]),
(S, "Which of the following is a main function of the International Monetary Fund (IMF)?", ["Promoting exchange rate stability and giving short-term loans to countries with balance of payments problems", "Printing the currency of member countries", "Fixing the price of oil for member countries", "Giving military aid to member countries"], 0, "The IMF works for international monetary cooperation and stable exchange rates, and lends to countries facing balance of payments difficulties.", "The IMF has its headquarters in Washington D.C. and was established in 1944 at Bretton Woods.", [29]),
(S, "Kahuta Research Laboratories (the Engineering Research Laboratories) were established during the government of which leader?", ["Zia-ul-Haq", "Zulfikar Ali Bhutto", "Ayub Khan", "Benazir Bhutto"], 1, "The nuclear programme was started by Zulfikar Ali Bhutto, and the Engineering Research Laboratories at Kahuta were set up in 1976 during his government.", "The laboratories were later renamed Khan Research Laboratories (KRL) in 1981 after Dr A. Q. Khan.", [183]),
(S, "Which is regarded as the most authentic (highest ranked) book of Hadith?", ["Sunan Abu Dawud", "Sahih Muslim", "Jami at-Tirmidhi", "Sahih Bukhari"], 3, "Sahih Bukhari, compiled by Imam Bukhari, is ranked first among the six authentic collections (Sihah Sitta).", "Sahih Muslim is ranked second, and together they are called the Sahihain.", [269]),
(S, "Where is the headquarters of the CIA (Central Intelligence Agency) located?", ["Langley, Virginia, USA", "New York City, USA", "Houston, Texas, USA", "Washington D.C. city centre"], 0, "The CIA headquarters is in Langley (McLean area), Virginia, near Washington D.C.", "The CIA was established in 1947 under the National Security Act.", [370]),
(S, "Which vitamin helps in the healing of wounds?", ["Vitamin A", "Vitamin D", "Vitamin C", "Vitamin K2"], 2, "Vitamin C (ascorbic acid) is needed to make collagen, which repairs skin and wounds.", "Deficiency of vitamin C causes scurvy.", [83]),
(S, "In which country is the city of Heidelberg located?", ["Austria", "Germany", "Switzerland", "Netherlands"], 1, "Heidelberg is a city in south-western Germany in the state of Baden-Wuerttemberg on the Neckar river.", "Heidelberg University, founded in 1386, is the oldest university in Germany.", [350]),
(S, "Which country has the highest number of satellites in orbit?", ["China", "Russia", "India", "United States of America"], 3, "The United States owns by far the largest number of active satellites, mainly because of large constellations such as Starlink.", "Sputnik 1 of the Soviet Union in 1957 was the first artificial satellite.", [401]),
(S, "In which year (Nabwi) did the first Hijrat (migration) of Muslims to Habsha (Abyssinia) take place?", ["1 Nabwi", "3 Nabwi", "5 Nabwi", "10 Nabwi"], 2, "The first migration to Abyssinia took place in the 5th year of prophethood (about 615 AD) to escape the persecution of Quraish.", "The king Najashi (Negus) gave shelter to the Muslims; some sources differ on the date of the second migration.", [335]),
(S, "What is the capital of the Holy See?", ["Rome", "Vatican City", "Florence", "Milan"], 1, "The Holy See is the government of the Catholic Church and is based in Vatican City.", "Vatican City is the smallest independent state in the world and lies inside Rome.", [257]),
(S, "Which of the following was a paternal aunt (Phuphi) of the Holy Prophet (PBUH)?", ["Hazrat Safiyya bint Abdul Muttalib", "Hazrat Khadija bint Khuwaylid", "Hazrat Fatima bint Muhammad", "Hazrat Asma bint Abu Bakr"], 0, "Safiyya was a daughter of Abdul Muttalib and so a paternal aunt of the Prophet (PBUH).", "Other paternal aunts include Atika, Arwa, Umm Hakim al-Bayda, Barra and Umaima.", [289]),
(S, "Which idol was worshipped by the people of Taif?", ["Hubal", "Manat", "Al-Lat", "Wadd"], 2, "Al-Lat was the main idol of the Thaqif tribe of Taif.", "Al-Uzza was worshipped near Nakhla and Manat near Qudayd, and Hubal was the chief idol inside the Kaaba.", [405]),
(S, "On which date did India conduct its Pokhran-II nuclear tests in 1998?", ["28 May 1998", "11 May 1998", "6 August 1998", "15 March 1998"], 1, "India carried out the first of its Pokhran-II tests on 11 May 1998, followed by more tests on 13 May.", "Pakistan answered with its tests at Chagai on 28 May 1998; India's first test was in 1974.", [318]),
(S, "The Indian Councils Act of 1909 is also known as what?", ["Montagu-Chelmsford Reforms", "Morley-Minto Reforms", "Government of India Act 1935", "Cabinet Mission Plan"], 1, "The Indian Councils Act 1909 was introduced by Lord Morley (Secretary of State) and Lord Minto (Viceroy), so it is called the Morley-Minto Reforms.", "It gave Muslims separate electorates.", [208]),
(S, "How many barrages are built on the River Indus in Pakistan?", ["4", "5", "6", "8"], 2, "The six barrages on the Indus are Jinnah, Chashma, Taunsa, Guddu, Sukkur and Kotri.", "Sukkur Barrage, completed in 1932, is the oldest of them.", [121]),
(S, "What is the approximate length of the Indus Highway (N-55) in Pakistan?", ["1264 km", "800 km", "2000 km", "560 km"], 0, "The Indus Highway runs from Karachi to Peshawar along the Indus river and is about 1264 km long.", "It is numbered N-55 in the national highway network.", [278]),
(S, "Which was the first institution (school) of Islam?", ["Suffah", "Darul Arqam", "Nizamiyya", "Al-Azhar"], 0, "Suffah, a raised platform at the Prophet's Mosque in Madina, was the first residential school of Islam where Ashab-e-Suffah studied.", "Darul Arqam was the early meeting place of Muslims in Makkah.", [314]),
(S, "Kalam Valley is located in which district of Khyber Pakhtunkhwa?", ["Chitral", "Swat", "Dir", "Kohistan"], 1, "Kalam is a popular valley at the top of the Swat valley in Swat district.", "The Swat river starts near Kalam from the Ushu and Utror streams.", [151, 355]),
(S, "The Khojak Pass in Balochistan lies in Qila Abdullah district and leads towards which border town?", ["Torkham", "Chaman", "Zhob", "Taftan"], 1, "The Khojak Pass in the Khwaja Amran range leads from Qila Abdullah to Chaman on the Afghan border.", "The Khojak Rail Tunnel is one of the longest railway tunnels in Pakistan.", [210, 420]),
(S, "How many Muslims and how many disbelievers (Kuffar) took part in the Ghazwa of Khandaq?", ["300 Muslims and 1000 Kuffar", "1000 Muslims and 3000 Kuffar", "3000 Muslims and 10000 Kuffar", "7000 Muslims and 30000 Kuffar"], 2, "About 3000 Muslims defended Madina against a combined army of about 10000 from the Quraish and their allies.", "The trench was dug on the advice of Hazrat Salman Farsi (RA).", [124]),
(S, "Who was the leader of the Quraish (disbelievers) army in the Ghazwa of Khandaq?", ["Abu Jahl", "Abu Sufyan", "Walid bin Mughira", "Ubayy bin Khalaf"], 1, "Abu Sufyan, who had not yet accepted Islam, led the Quraish in the Battle of Khandaq. Abu Jahl had been killed earlier at Badr.", "Abu Sufyan accepted Islam at the conquest of Makkah in 8 AH.", [473]),
(S, "In which district of Punjab is Namal (Numal) Lake located?", ["Mianwali", "Jhelum", "Attock", "Sargodha"], 0, "Namal Lake is an artificial lake in Mianwali district near the Namal Valley.", "It lies in the Salt Range area.", [362]),
(S, "Hamza Baba is a famous poet of which language?", ["Urdu", "Sindhi", "Pashto", "Balochi"], 2, "Hamza Baba (Hamza Shinwari) was a well-known Pashto poet of Khyber Pakhtunkhwa.", "Khushal Khan Khattak and Rahman Baba are other great Pashto poets.", [116]),
(S, "What is the meaning of the word Urdu in the Turkish language?", ["Poetry", "Army (camp)", "Language", "Market"], 1, "The word Urdu comes from Turkish ordu which means army or military camp.", "Urdu developed in the army camps and bazaars of the Mughal period.", [287]),
(S, "Which is the highest (tallest) waterfall in the world?", ["Niagara Falls", "Victoria Falls", "Angel Falls", "Iguazu Falls"], 2, "Angel Falls in Venezuela has a height of about 979 metres and is the tallest uninterrupted waterfall.", "Victoria Falls lies between Zambia and Zimbabwe.", [276]),
(S, "What is the approximate length of the Line of Control (LOC) between Pakistan and India in Kashmir?", ["740 km", "1046 km", "2912 km", "450 km"], 0, "The Line of Control is about 740 km long, as commonly stated.", "It was established after the 1971 war by the Simla Agreement of 1972; sources give slightly different lengths.", [279]),
(S, "Which country has the lengthiest written constitution in the world?", ["United States", "India", "Pakistan", "United Kingdom"], 1, "The Constitution of India is the longest written constitution of any sovereign country.", "It was adopted in 1949 and came into force on 26 January 1950.", [408, 409]),
(S, "Which strait lies between Greenland and Iceland?", ["Bering Strait", "Denmark Strait", "Strait of Gibraltar", "Davis Strait"], 1, "The Denmark Strait separates Greenland from Iceland and links the Arctic and Atlantic oceans.", "Davis Strait lies between Greenland and Canada.", [430]),
(S, "In which province of Pakistan is Hanna Lake located?", ["Punjab", "Sindh", "Balochistan", "Khyber Pakhtunkhwa"], 2, "Hanna Lake is a lake near Quetta in Balochistan.", "It lies in the Zarghun mountains area.", [348]),
(S, "Kachura Lake is located near which city?", ["Skardu", "Gilgit", "Chitral", "Murree"], 0, "Upper and Lower Kachura Lakes are near Skardu in Gilgit-Baltistan.", "Lower Kachura is also called Shangrila Lake.", [353]),
(S, "Rawal Lake is located in which city?", ["Lahore", "Islamabad", "Peshawar", "Quetta"], 1, "Rawal Lake is an artificial reservoir in Islamabad that supplies water to Rawalpindi and Islamabad.", "It is fed by the Korang River.", [365]),
]
